for (const item of $input.all()) {
  try {
    // Gemini returns the text inside candidates[0].content.parts[0].text
    const textResponse = item.json.candidates[0].content.parts[0].text;
    item.json = JSON.parse(textResponse);
  } catch (e) {
    item.json = { error: "Failed to parse response", details: e.message };
  }
}
return $input.all();
